const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const text = String(input.text || input.message_text || input.texto_mensaje || '').trim();
const textLower = text.toLowerCase();

const requestId = input.request_id || `req_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
const role = input.role || 'professional';

let route = 'unknown';
let confidence = 0.5;
let reply = 'He recibido tu mensaje. Lo reviso y te respondo enseguida.';

if (/\b(cita|agendar|agenda|reservar|reserva|hueco|hora|calendario)\b/i.test(textLower)) {
  route = 'appointment';
  confidence = 0.9;
  reply = 'Perfecto. Voy a gestionar tu solicitud de cita.';
} else if (/\b(ejercicio|estiramiento|rutina|movilidad|fortalecimiento|plan)\b/i.test(textLower)) {
  route = 'exercise';
  confidence = 0.85;
  reply = 'Perfecto. Voy a preparar una recomendacion de ejercicio.';
} else if (/\b(dolor|sintoma|sintomas|molestia|lesion|evolucion|seguimiento)\b/i.test(textLower)) {
  route = 'session_note';
  confidence = 0.8;
  reply = 'Gracias. Dejo registrado tu seguimiento clinico.';
} else if (text.length === 0) {
  route = 'unknown';
  confidence = 0.2;
  reply = 'No he podido leer el contenido del mensaje. Puedes reenviarlo en texto, por favor?';
}

return [{
  json: {
    ok: true,
    request_id: requestId,
    role,
    route,
    confidence,
    reply_text: reply,
    intent_hint: route,
    normalized_payload: {
      text,
      channel: input.channel || 'web',
      patient_id: input.paciente_id || input.patient_id || null,
      professional_id: input.profesional_id || input.professional_id || null
    },
    received: {
      channel: input.channel || 'web',
      paciente_id: input.paciente_id || input.patient_id || null,
      profesional_id: input.profesional_id || input.professional_id || null,
      text
    }
  }
}];
